-- Migration 070 (data): Informatics 10, chapter 2 "Data representation" — 3 lessons + Check yourself. Needs 069 (test variants).
-- Idempotent: lessons are found by plan->>'gen'. The module keeps only these lessons; former ones leave the module, their rows stay.

do $info10$
declare v_course uuid; v_owner uuid; v_school uuid; v_module uuid; v_lesson uuid; v_spec record; v_ids uuid[] := '{}';
begin
  select c.id, c.owner_id, c.school_id into v_course, v_owner, v_school from public.cf_curr_courses c where c.title = $i10$informatics 10th$i10$ and c.grade = 10 order by c.created_at limit 1;
  if v_course is null then raise exception 'Курс табылмады: informatics 10th'; end if;
  select m.id into v_module from public.cf_curr_modules m where m.course_id = v_course and m.title = $i10$2-тарау. Деректерді көрсету$i10$ limit 1;
  if v_module is null then raise exception 'Модуль табылмады: 2-тарау. Деректерді көрсету'; end if;

  for v_spec in select * from (values
    ($i10$inf10-1$i10$, $i10$2.1 Сандар жүйелері және екілік арифметика$i10$, $i10$Информатика$i10$, 0, $i10${"gen":"inf10-1","summary":"Позициялық жүйелер (2, 8, 10, 16), бір жүйеден екіншісіне аудару, екілік және 16-лық сандарды бағанмен қосу мен азайту.","objectives":["Санды 2, 8, 10, 16-лық жүйелер арасында аудару","Екілік сандарды қосу және азайту, нәтижені ондықта тексеру"],"grade":10,"duration":"45 минут","prior":"Ондық жүйені, дәрежені біледі; бит пен байт ұғымы таныс (8–9-сынып).","env":"ClassFlow: интерактивті слайдтар (сандар жүйесі, схемалар, кодтар) және «Көмекші кесте» (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC функциялары). Әр оқушыға құрылғы мен интернет.","source":"Информатика 10-сынып оқулығы, 2-тарау «Деректерді көрсету» (беттерін мұғалім нақтылайды). Барлық жауап бағдарламамен есептеліп тексерілген.","stages":[{"k":"warmup","min":5,"do":"Екі сұрақ: цифрлар саны, байт"},{"k":"together","min":10,"do":"Позициялық жүйе, 10 → 2 аудару, биттерді топтау (8 және 16)"},{"k":"example","min":8,"do":"Бағанмен қосу және азайтуды құралда қадамдап көреді"},{"k":"practice","min":15,"do":"5 есеп (көмекші кестемен тексеруге болады); үлгерген оқушы ★"},{"k":"check","min":7,"do":"Екі тест сұрағы және қорытынды"}],"ru":{"summary":"Позиционные системы (2, 8, 10, 16), перевод между ними, сложение и вычитание столбиком в двоичной и шестнадцатеричной системе.","objectives":["Переводить числа между системами 2, 8, 10, 16","Складывать и вычитать двоичные числа, проверять в десятичной"],"prior":"Знают десятичную систему и степени; знакомы бит и байт (8–9 класс).","env":"ClassFlow: интерактивные слайды (системы счисления, схемы, коды) и «Таблица-помощник» (функции DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). Каждому ученику устройство и интернет.","source":"Учебник информатики 10 класса, глава 2 «Представление данных» (страницы уточняет учитель). Все ответы вычислены и проверены программой.","stages":["Два вопроса: число цифр, байт","Позиционная система, перевод 10 → 2, группировка битов (8 и 16)","Пошагово смотрит сложение и вычитание столбиком в инструменте","5 задач (можно проверять в таблице-помощнике); кто успел — ★","Два тестовых вопроса и итог"]},"en":{"summary":"Positional systems (2, 8, 10, 16), converting between them, column addition and subtraction in binary and hexadecimal.","objectives":["Convert numbers between bases 2, 8, 10 and 16","Add and subtract binary numbers and check in decimal"],"prior":"Know the decimal system and powers; know bits and bytes (Grades 8–9).","env":"ClassFlow: interactive slides (number systems, circuits, codes) and the “Helper sheet” (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). A device and the internet per student.","source":"Informatics Grade 10 textbook, chapter 2 “Data representation” (the teacher adds the pages). Every answer was computed and checked by a program.","stages":["Two questions: number of digits, the byte","Positional systems, 10 → 2, grouping bits (8 and 16)","Steps through column addition and subtraction in the tool","5 problems (the helper sheet can check); fast students take ★","Two test questions and the wrap-up"]}}$i10$::jsonb, $i10$[{"term":"base","definition":"Жүйенің негізі — қолданылатын цифрлар саны (2, 8, 10, 16) · Основание системы — число используемых цифр (2, 8, 10, 16) · Base — the number of digits a system uses (2, 8, 10, 16)"},{"term":"bit","definition":"Бит — екілік разряд: 0 немесе 1 · Бит — двоичный разряд: 0 или 1 · Bit — one binary digit: 0 or 1"},{"term":"hexadecimal","definition":"Он алтылық жүйе — 0–9 және A–F цифрлары; 4 бит = 1 цифр · Шестнадцатеричная система — цифры 0–9 и A–F; 4 бита = 1 цифра · Hexadecimal — digits 0–9 and A–F; 4 bits = 1 digit"},{"term":"carry","definition":"Ауыстыру — разряд толғанда келесі разрядқа көшетін 1 · Перенос — 1, переходящая в следующий разряд при переполнении · Carry — the 1 that moves to the next column when a column overflows"}]$i10$::jsonb, $i10$[{"type":"title","pageType":"slide","templateId":"title","title":"2.1 Сандар жүйелері және екілік арифметика","subtitle":"Информатика 10-сынып · 2-тарау «Деректерді көрсету»","ru":{"title":"2.1 Системы счисления и двоичная арифметика","subtitle":"Информатика 10 класс · глава 2 «Представление данных»"},"en":{"title":"2.1 Number systems and binary arithmetic","subtitle":"Informatics Grade 10 · Chapter 2 “Data representation”"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: цифрлар","prompt":"Ондық жүйеде неше түрлі цифр бар?","options":["9","10","11","2"],"answer":1,"explanation":"0, 1, …, 9 — он цифр. Жүйенің негізі = цифрлар саны.","points":1,"ru":{"title":"Повторение: цифры","prompt":"Сколько разных цифр в десятичной системе?","options":["9","10","11","2"],"explanation":"0, 1, …, 9 — десять цифр. Основание = число цифр.","notes":"5 минут. Два вопроса — разминка. После ответов сразу переходите к понятию «основание»."},"en":{"title":"Review: digits","prompt":"How many different digits does the decimal system have?","options":["9","10","11","2"],"explanation":"0, 1, …, 9 — ten digits. The base equals the number of digits.","notes":"5 minutes. Two quick questions; go straight on to the idea of a base."},"stage":"warmup","notes":"5 минут. Екі сұрақ — 10-сынып үшін жылы кіріс. Жауаптардан кейін бірден «негіз» ұғымына көшіңіз."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: байт","prompt":"1 байтта неше бит бар?","options":["2","16","10","8"],"answer":3,"explanation":"1 байт = 8 бит, сондықтан 1 байтпен 2⁸ = 256 түрлі мән жазылады.","points":1,"ru":{"title":"Повторение: байт","prompt":"Сколько бит в 1 байте?","options":["2","16","10","8"],"explanation":"1 байт = 8 бит, поэтому в 1 байт помещается 2⁸ = 256 значений."},"en":{"title":"Review: byte","prompt":"How many bits are in 1 byte?","options":["2","16","10","8"],"explanation":"1 byte = 8 bits, so a byte holds 2⁸ = 256 values."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Позициялық жүйе: цифрдың салмағы орнында","bullets":["Негізі b жүйеде цифрлар 0 … b−1, разрядтың салмағы — b-ның дәрежесі: …, b², b¹, b⁰.","Ондыққа аудару: цифр × салмақ, сосын қосамыз. 1011₂ = 8 + 0 + 2 + 1 = 11.","Компьютер екілік жүйемен жұмыс істейді: транзистордың екі күйі бар — ток бар (1), жоқ (0)."],"notes":"10 минут (бірлескен бөлім). Құралда санды өзгертіп, әр цифрдың астындағы салмақты көрсетіңіз. Сұраңыз: 1011₈ қанша? (521).","ru":{"title":"Позиционная система: вес цифры зависит от места","bullets":["В системе с основанием b цифры 0 … b−1, вес разряда — степень b: …, b², b¹, b⁰.","В десятичную: цифра × вес и сложить. 1011₂ = 8 + 0 + 2 + 1 = 11.","Компьютер работает в двоичной: у транзистора два состояния — ток есть (1), нет (0)."],"notes":"10 минут (совместная часть). Меняйте число в инструменте и показывайте вес под каждой цифрой. Спросите: сколько будет 1011₈? (521)."},"en":{"title":"Positional system: a digit’s weight depends on its place","bullets":["In base b the digits are 0 … b−1; each place weighs a power of b: …, b², b¹, b⁰.","To decimal: digit × weight, then add. 1011₂ = 8 + 0 + 2 + 1 = 11.","Computers use binary: a transistor has two states — current (1) or none (0)."],"notes":"10 minutes (together). Change the number in the tool and show the weight under every digit. Ask: what is 1011₈? (521)."},"widget":{"kind":"base","mode":"convert","value":"1011","from":2,"to":10},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ондықтан екілікке: 2-ге бөлеміз","bullets":["Санды 2-ге бөліп, қалдықты жазамыз; бөліндіні қайта бөлеміз — 0 болғанша.","Қалдықтарды төменнен жоғары оқимыз. Басқа жүйеге — сол жүйенің негізіне бөлеміз."],"ru":{"title":"Из десятичной в двоичную: делим на 2","bullets":["Делим число на 2, записываем остаток; частное снова делим — пока не получим 0.","Остатки читаем снизу вверх. В другую систему — делим на её основание."]},"en":{"title":"Decimal to binary: divide by 2","bullets":["Divide by 2 and write the remainder; divide the quotient again until it is 0.","Read the remainders bottom-up. For another base, divide by that base."]},"widget":{"kind":"base","mode":"convert","value":"199","from":10,"to":2},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"8 және 16-лық жүйе: биттерді топтаймыз","bullets":["8 = 2³: оңнан 3 биттен топтаймыз; 16 = 2⁴: 4 биттен. Әр топ — бір цифр.","16-лық цифрлар: A=10, B=11, C=12, D=13, E=14, F=15. Түстер (#FF8800), MAC-адрестер осылай жазылады."],"ru":{"title":"Системы 8 и 16: группируем биты","bullets":["8 = 2³: группы по 3 бита справа; 16 = 2⁴: по 4. Каждая группа — одна цифра.","Цифры 16-ричной: A=10 … F=15. Так пишут цвета (#FF8800) и MAC-адреса."]},"en":{"title":"Bases 8 and 16: group the bits","bullets":["8 = 2³: groups of 3 bits from the right; 16 = 2⁴: groups of 4. Each group is one digit.","Hex digits: A=10 … F=15. Colours (#FF8800) and MAC addresses are written this way."]},"widget":{"kind":"base","mode":"convert","value":"11010110","from":2,"to":16},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Екілік қосу: 1 + 1 = 10","bullets":["Оңнан солға разрядпен қосамыз. 1 + 1 = 10: 0 жазамыз, 1 келесі разрядқа көшеді.","1 + 1 + 1 (ауыстырумен) = 11: 1 жазамыз, 1 көшеді. Соңында ондықта тексереміз."],"notes":"8 минут (мысал). «Келесі разряд» батырмасын баса отырып, сыныптан келесі цифрды сұраңыз. Жүйені 16-ға ауыстырып, FF + 1 мысалын көрсетіңіз.","ru":{"title":"Двоичное сложение: 1 + 1 = 10","bullets":["Складываем справа налево. 1 + 1 = 10: пишем 0, 1 переносим в следующий разряд.","1 + 1 + 1 (с переносом) = 11: пишем 1, 1 переносим. В конце проверяем в десятичной."],"notes":"8 минут (пример). Нажимая «Следующий разряд», спрашивайте у класса следующую цифру. Переключите на 16 и покажите FF + 1."},"en":{"title":"Binary addition: 1 + 1 = 10","bullets":["Add column by column from the right. 1 + 1 = 10: write 0, carry 1.","1 + 1 + 1 (with a carry) = 11: write 1, carry 1. Check the result in decimal."],"notes":"8 minutes (example). Press “Next column” and ask the class for each digit. Switch to base 16 and show FF + 1."},"widget":{"kind":"base","mode":"arith","base":2,"a":"11010","b":"1100","op":"+"},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Екілік азайту: көршіден қарызға аламыз","bullets":["0 − 1 болмайды: сол жақтағы разрядтан 1 аламыз, ол бұл разрядта 2-ге тең: 10 − 1 = 1.","Қарыз берген разряд 1-ге азаяды (құралда • белгісі). Келесі сабақта азайтуды қосымша кодпен қосуға айналдырамыз."],"ru":{"title":"Двоичное вычитание: заём у соседа","bullets":["0 − 1 нельзя: берём 1 у левого разряда, здесь она равна 2: 10 − 1 = 1.","Разряд, давший заём, уменьшается на 1 (знак • в инструменте). В уроке 2.3 вычитание станет сложением с дополнительным кодом."]},"en":{"title":"Binary subtraction: borrow from the left","bullets":["0 − 1 is impossible: borrow 1 from the left; here it is worth 2: 10 − 1 = 1.","The column that lent drops by 1 (• in the tool). In lesson 2.3 subtraction becomes addition with two’s complement."]},"widget":{"kind":"base","mode":"arith","base":2,"a":"110010","b":"1011","op":"-"},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Аудару: 10 → 2","prompt":"173 санын екілік жүйеге аудар.","accept":["10101101"],"points":2,"notes":"15 минут. Оқушылар дәптерде шығарады, «Көмекші кесте» тек тексеру үшін: =DEC2BIN(173). Күтілетін жауаптар: 10101101, AD, 1001000, 111011, 253; ★ 100.","ru":{"title":"Перевод: 10 → 2","prompt":"Переведи число 173 в двоичную систему.","notes":"15 минут. Решают в тетради, «Таблица-помощник» — только для проверки: =DEC2BIN(173). Ответы: 10101101, AD, 1001000, 111011, 253; ★ 100."},"en":{"title":"Convert: 10 → 2","prompt":"Convert 173 to binary.","notes":"15 minutes. Students solve on paper; the helper sheet only checks: =DEC2BIN(173). Answers: 10101101, AD, 1001000, 111011, 253; ★ 100."},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Аудару: 2 → 16","prompt":"10101101₂ санын 16-лық жүйеге аудар (4 биттен топта).","accept":["AD"],"points":2,"ru":{"title":"Перевод: 2 → 16","prompt":"Переведи 10101101₂ в 16-ричную систему (группы по 4 бита)."},"en":{"title":"Convert: 2 → 16","prompt":"Convert 10101101₂ to hexadecimal (groups of 4 bits)."},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Екілік қосу","prompt":"101101₂ + 11011₂ = ? (жауапты екілік жүйеде жаз)","accept":["1001000"],"points":2,"ru":{"title":"Двоичное сложение","prompt":"101101₂ + 11011₂ = ? (ответ в двоичной)"},"en":{"title":"Binary addition","prompt":"101101₂ + 11011₂ = ? (answer in binary)"},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Екілік азайту","prompt":"1000000₂ − 101₂ = ? (екілік жүйеде)","accept":["111011"],"points":2,"ru":{"title":"Двоичное вычитание","prompt":"1000000₂ − 101₂ = ? (в двоичной)"},"en":{"title":"Binary subtraction","prompt":"1000000₂ − 101₂ = ? (in binary)"},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Аудару: 8 → 10","prompt":"375₈ санын ондық жүйеге аудар.","accept":["253"],"points":2,"ru":{"title":"Перевод: 8 → 10","prompt":"Переведи 375₈ в десятичную систему."},"en":{"title":"Convert: 8 → 10","prompt":"Convert 375₈ to decimal."},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"★ Күрделі есеп: 16-лық қосу","prompt":"FF₁₆ + 1₁₆ = ?₁₆ Неге нәтиже 3 цифрлы болды?","accept":["100"],"points":3,"notes":"F + 1 = 16 = 10₁₆: 0 жазып, 1 көшеді — екі рет. Екілікте дәл осы: 11111111 + 1 = 100000000 (1 байттан асады).","ru":{"title":"★ Сложная задача: сложение в 16-ричной","prompt":"FF₁₆ + 1₁₆ = ?₁₆ Почему результат трёхзначный?","notes":"F + 1 = 16 = 10₁₆: пишем 0, переносим 1 — дважды. В двоичной то же: 11111111 + 1 = 100000000 (больше байта)."},"en":{"title":"★ Hard problem: hex addition","prompt":"FF₁₆ + 1₁₆ = ?₁₆ Why does the result have three digits?","notes":"F + 1 = 16 = 10₁₆: write 0, carry 1 — twice. Binary does the same: 11111111 + 1 = 100000000 (more than a byte)."},"helper":true,"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: қосу","prompt":"1011₂ + 1₂ = ?","options":["1012","1111","1100","10110"],"answer":2,"explanation":"1 + 1 = 10 (0 жазып, 1 көшеді), тағы 1 + 1 = 10, сосын 0 + 1 = 1: 1100₂ = 12 = 11 + 1.","points":1,"ru":{"title":"Тест: сложение","prompt":"1011₂ + 1₂ = ?","options":["1012","1111","1100","10110"],"explanation":"1 + 1 = 10 (пишем 0, переносим 1), снова 1 + 1 = 10, затем 0 + 1 = 1: 1100₂ = 12 = 11 + 1.","notes":"7 минут: два теста и итог. Тем, кто выбрал 1012, напомните: в двоичной нет цифры «2»."},"en":{"title":"Test: addition","prompt":"1011₂ + 1₂ = ?","options":["1012","1111","1100","10110"],"explanation":"1 + 1 = 10 (write 0, carry 1), again 1 + 1 = 10, then 0 + 1 = 1: 1100₂ = 12 = 11 + 1.","notes":"7 minutes: two tests and the wrap-up. Remind those who chose 1012 that binary has no digit “2”."},"stage":"check","notes":"7 минут: екі тест және қорытынды. 1012 жауабын таңдағандарға екілікте «2» цифры жоқ екенін еске салыңыз."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: 16 → 10","prompt":"1F₁₆ ондық жүйеде неге тең?","options":["31","115","25","16"],"answer":0,"explanation":"1 · 16 + F · 1 = 16 + 15 = 31.","points":1,"ru":{"title":"Тест: 16 → 10","prompt":"Чему равно 1F₁₆ в десятичной?","options":["31","115","25","16"],"explanation":"1 · 16 + F · 1 = 16 + 15 = 31."},"en":{"title":"Test: 16 → 10","prompt":"What is 1F₁₆ in decimal?","options":["31","115","25","16"],"explanation":"1 · 16 + F · 1 = 16 + 15 = 31."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$i10$::jsonb),
    ($i10$inf10-2$i10$, $i10$2.2 Логикалық элементтер мен схемалар$i10$, $i10$Информатика$i10$, 1, $i10${"gen":"inf10-2","summary":"AND, OR, NOT, XOR, NAND, NOR вентильдері; ақиқат кестесін құру; бірнеше вентильден тұратын схеманың шығысын табу.","objectives":["Негізгі вентильдердің жұмысын ақиқат кестесімен сипаттау","Схеманың шығысын кез келген кіріс үшін анықтау"],"grade":10,"duration":"45 минут","prior":"Ақиқат/жалған ұғымы, екілік сандар (2.1); Python-да and, or, not таныс.","env":"ClassFlow: интерактивті слайдтар (сандар жүйесі, схемалар, кодтар) және «Көмекші кесте» (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC функциялары). Әр оқушыға құрылғы мен интернет.","source":"Информатика 10-сынып оқулығы, 2-тарау «Деректерді көрсету» (беттерін мұғалім нақтылайды). Барлық жауап бағдарламамен есептеліп тексерілген.","stages":[{"k":"warmup","min":5,"do":"Екі сұрақ: тұжырым, кесте жолдары"},{"k":"together","min":10,"do":"Вентильдерді құралда сынап, ақиқат кестесін құрады"},{"k":"example","min":8,"do":"Күзет дабылы мен XOR схемасын бірге талдайды"},{"k":"practice","min":15,"do":"Схемалармен 3 есеп; үлгерген оқушы ★ (дауыс беру схемасы)"},{"k":"check","min":7,"do":"Екі тест сұрағы және қорытынды"}],"ru":{"summary":"Вентили AND, OR, NOT, XOR, NAND, NOR; построение таблицы истинности; выход схемы из нескольких вентилей.","objectives":["Описывать работу основных вентилей таблицей истинности","Определять выход схемы для любых входов"],"prior":"Понятия истина/ложь, двоичные числа (2.1); знакомы and, or, not в Python.","env":"ClassFlow: интерактивные слайды (системы счисления, схемы, коды) и «Таблица-помощник» (функции DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). Каждому ученику устройство и интернет.","source":"Учебник информатики 10 класса, глава 2 «Представление данных» (страницы уточняет учитель). Все ответы вычислены и проверены программой.","stages":["Два вопроса: высказывание, строки таблицы","Испытывает вентили в инструменте, строит таблицу истинности","Вместе разбирает сигнализацию и схему XOR","3 задачи со схемами; кто успел — ★ (схема голосования)","Два тестовых вопроса и итог"]},"en":{"summary":"AND, OR, NOT, XOR, NAND, NOR gates; building a truth table; finding the output of a circuit of several gates.","objectives":["Describe the basic gates with truth tables","Find a circuit’s output for any inputs"],"prior":"True/false, binary numbers (2.1); and, or, not in Python.","env":"ClassFlow: interactive slides (number systems, circuits, codes) and the “Helper sheet” (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). A device and the internet per student.","source":"Informatics Grade 10 textbook, chapter 2 “Data representation” (the teacher adds the pages). Every answer was computed and checked by a program.","stages":["Two questions: a statement, table rows","Tries the gates in the tool and builds a truth table","Works through an alarm circuit and an XOR circuit","3 circuit problems; fast students take ★ (the majority circuit)","Two test questions and the wrap-up"]}}$i10$::jsonb, $i10$[{"term":"logic gate","definition":"Логикалық вентиль — 0/1 кірістерден 0/1 шығыс жасайтын электрондық элемент · Логический вентиль — элемент, превращающий входы 0/1 в выход 0/1 · Logic gate — an element that turns 0/1 inputs into a 0/1 output"},{"term":"truth table","definition":"Ақиқат кестесі — кірістердің барлық 2ⁿ комбинациясы мен шығысы · Таблица истинности — все 2ⁿ комбинации входов и выход · Truth table — every 2ⁿ input combination and its output"},{"term":"XOR","definition":"XOR (бөлек НЕМЕСЕ) — кірістер әртүрлі болса ғана 1 · XOR (исключающее ИЛИ) — 1, только если входы различны · XOR (exclusive OR) — 1 only when the inputs differ"},{"term":"NAND","definition":"NAND (ЖӘНЕ-ЕМЕС) — әмбебап вентиль: кез келген схеманы тек NAND-пен құруға болады · NAND (И-НЕ) — универсальный: любую схему можно собрать только из NAND · NAND — a universal gate: any circuit can be built from NAND alone"}]$i10$::jsonb, $i10$[{"type":"title","pageType":"slide","templateId":"title","title":"2.2 Логикалық элементтер мен схемалар","subtitle":"Информатика 10-сынып · 2-тарау «Деректерді көрсету»","ru":{"title":"2.2 Логические элементы и схемы","subtitle":"Информатика 10 класс · глава 2 «Представление данных»"},"en":{"title":"2.2 Logic gates and circuits","subtitle":"Informatics Grade 10 · Chapter 2 “Data representation”"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: тұжырым","prompt":"«7 > 3 ЖӘНЕ 2 > 5» тұжырымының мәні қандай?","options":["Ақиқат (1)","Жалған (0)","7","Анықталмаған"],"answer":1,"explanation":"ЖӘНЕ екі бөлік те ақиқат болғанда ғана ақиқат; 2 > 5 жалған, сондықтан бәрі жалған.","points":1,"ru":{"title":"Повторение: высказывание","prompt":"Каково значение высказывания «7 > 3 И 2 > 5»?","options":["Истина (1)","Ложь (0)","7","Не определено"],"explanation":"И истинно, только если обе части истинны; 2 > 5 ложно, значит всё ложно.","notes":"5 минут. Запишите на доске «истина = 1, ложь = 0» — понадобится весь урок."},"en":{"title":"Review: statement","prompt":"What is the value of “7 > 3 AND 2 > 5”?","options":["True (1)","False (0)","7","Undefined"],"explanation":"AND is true only when both parts are; 2 > 5 is false, so the whole is false.","notes":"5 minutes. Write “true = 1, false = 0” on the board — you need it all lesson."},"stage":"warmup","notes":"5 минут. «Ақиқат = 1, жалған = 0» байланысын тақтаға жазып қойыңыз — сабақ бойы керек."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: жолдар саны","prompt":"Үш кірісті (A, B, C) схеманың ақиқат кестесінде неше жол болады?","options":["3","6","9","8"],"answer":3,"explanation":"Әр кіріс 0 немесе 1: 2 · 2 · 2 = 2³ = 8 комбинация.","points":1,"ru":{"title":"Повторение: число строк","prompt":"Сколько строк в таблице истинности схемы с тремя входами (A, B, C)?","options":["3","6","9","8"],"explanation":"Каждый вход 0 или 1: 2 · 2 · 2 = 2³ = 8 комбинаций."},"en":{"title":"Review: number of rows","prompt":"How many rows does the truth table of a 3-input circuit have?","options":["3","6","9","8"],"explanation":"Each input is 0 or 1: 2 · 2 · 2 = 2³ = 8 combinations."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Негізгі вентильдер","bullets":["AND (ЖӘНЕ): екі кіріс те 1 болса ғана 1. OR (НЕМЕСЕ): кемінде біреуі 1 болса 1. NOT (ЕМЕС): кірісті керісінше етеді.","XOR: кірістер әртүрлі болса 1. NAND мен NOR — AND мен OR-дың шығысына NOT қосылған (сызбадағы кішкене дөңгелек).","Вентильді таңда, A мен B-ны бас: сары сым — 1 сигнал, кестеде қазіргі жол жарықтанады."],"notes":"10 минут. Әр вентильді тақтада сынап, сыныптан шығысты алдын ала болжауды сұраңыз. NAND-та «AND + NOT» екенін көрсетіңіз.","ru":{"title":"Основные вентили","bullets":["AND (И): 1, только если оба входа 1. OR (ИЛИ): 1, если хотя бы один 1. NOT (НЕ): инвертирует вход.","XOR: 1, если входы различны. NAND и NOR — это AND и OR с NOT на выходе (кружок на схеме).","Выбери вентиль, нажимай A и B: жёлтый провод — сигнал 1, в таблице подсвечена текущая строка."],"notes":"10 минут. Испытайте каждый вентиль на доске, просите класс заранее угадать выход. В NAND покажите «AND + NOT»."},"en":{"title":"The basic gates","bullets":["AND: 1 only if both inputs are 1. OR: 1 if at least one is 1. NOT: inverts the input.","XOR: 1 when the inputs differ. NAND and NOR are AND and OR followed by NOT (the small circle).","Pick a gate and click A and B: a yellow wire carries 1; the current row lights up in the table."],"notes":"10 minutes. Try every gate on the board and let the class predict the output first. Show that NAND is “AND + NOT”."},"widget":{"kind":"circuit","pick":true,"gate":"AND"},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Ақиқат кестесін құру","bullets":["1) 2ⁿ жол: кірістерді екілік санау ретімен жазамыз (000, 001, …, 111).","2) Әр аралық вентильге бөлек баған (P = A AND B, N = NOT C). 3) Соңғы баған — шығыс Q."],"code":"Q = (A AND B) OR NOT C","lang":"text","ru":{"title":"Построение таблицы истинности","bullets":["1) 2ⁿ строк: входы пишем в порядке двоичного счёта (000, 001, …, 111).","2) Для каждого промежуточного вентиля свой столбец (P = A AND B, N = NOT C). 3) Последний — выход Q."]},"en":{"title":"Building a truth table","bullets":["1) 2ⁿ rows: write the inputs in binary counting order (000, 001, …, 111).","2) One column per inner gate (P = A AND B, N = NOT C). 3) The last column is the output Q."]},"widget":{"kind":"circuit","circuit":{"inputs":["A","B","C"],"gates":[{"id":"P","type":"AND","in":["A","B"]},{"id":"N","type":"NOT","in":["C"]},{"id":"Q","type":"OR","in":["P","N"]}],"out":"Q"}},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"Мысал: күзет дабылы","bullets":["Дабыл (Q) күзет қосулы (S = 1) және есік (D) НЕМЕСЕ терезе (W) ашық болғанда шырылдайды.","Q = (D OR W) AND S. Кестеден: 8 жолдың тек 3-інде Q = 1."],"notes":"8 минут (мысал). Алдымен сыныптан ауызша формуланы құрастыруды сұраңыз, сосын схемада тексеріңіз. Екінші мысалда XOR-ды AND/OR/NOT-пен жинаймыз.","ru":{"title":"Пример: охранная сигнализация","bullets":["Сигнализация (Q) звенит, если охрана включена (S = 1) и открыта дверь (D) ИЛИ окно (W).","Q = (D OR W) AND S. По таблице: только в 3 строках из 8 Q = 1."],"notes":"8 минут (пример). Сначала пусть класс сам составит формулу словами, затем проверьте на схеме. Во втором примере собираем XOR из AND/OR/NOT."},"en":{"title":"Example: a burglar alarm","bullets":["The alarm (Q) rings when it is armed (S = 1) and the door (D) OR the window (W) is open.","Q = (D OR W) AND S. The table shows Q = 1 in only 3 of the 8 rows."],"notes":"8 minutes (example). Let the class build the formula in words first, then check it on the circuit. The second example builds XOR from AND/OR/NOT."},"widget":{"kind":"circuit","circuit":{"inputs":["D","W","S"],"gates":[{"id":"P","type":"OR","in":["D","W"]},{"id":"Q","type":"AND","in":["P","S"]}],"out":"Q"}},"stage":"example"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"example","title":"XOR-ды AND, OR, NOT-пен жинаймыз","bullets":["«Біреуі 1, бірақ екеуі бірге емес»: Q = (A OR B) AND NOT (A AND B).","Кестедегі Q бағанын XOR кестесімен салыстыр: 0110 — бірдей."],"ru":{"title":"Собираем XOR из AND, OR, NOT","bullets":["«Один из них 1, но не оба»: Q = (A OR B) AND NOT (A AND B).","Сравни столбец Q с таблицей XOR: 0110 — совпадает."]},"en":{"title":"Building XOR from AND, OR, NOT","bullets":["“One of them is 1, but not both”: Q = (A OR B) AND NOT (A AND B).","Compare the Q column with the XOR table: 0110 — the same."]},"widget":{"kind":"circuit","circuit":{"inputs":["A","B"],"gates":[{"id":"P","type":"OR","in":["A","B"]},{"id":"N","type":"AND","in":["A","B"]},{"id":"M","type":"NOT","in":["N"]},{"id":"Q","type":"AND","in":["P","M"]}],"out":"Q"}},"stage":"example"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Схема: шығысты тап","prompt":"A = 1, B = 1, C = 0 болғанда Q неге тең? (0 немесе 1)","accept":["0"],"points":2,"notes":"15 минут. Схемада шығыс жасырулы: оқушы аралық сымдарды көріп, соңғы вентильді өзі есептейді. Жауаптар: 0; 00010100; 4; ★ 00010111.","ru":{"title":"Схема: найди выход","prompt":"Чему равен Q при A = 1, B = 1, C = 0? (0 или 1)","notes":"15 минут. Выход на схеме скрыт: ученик видит промежуточные провода и сам считает последний вентиль. Ответы: 0; 00010100; 4; ★ 00010111."},"en":{"title":"Circuit: find the output","prompt":"What is Q for A = 1, B = 1, C = 0? (0 or 1)","notes":"15 minutes. The output is hidden: students see the inner wires and work out the last gate. Answers: 0; 00010100; 4; ★ 00010111."},"widget":{"kind":"circuit","circuit":{"inputs":["A","B","C"],"gates":[{"id":"P","type":"AND","in":["A","B"]},{"id":"N","type":"NOT","in":["P"]},{"id":"Q","type":"OR","in":["N","C"]}],"out":"Q"},"hideOut":true},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Ақиқат кестесі: Q бағаны","prompt":"Q бағанын жоғарыдан төмен 8 цифрмен жаз (мысалы 01010101).","accept":["00010100"],"points":2,"ru":{"title":"Таблица истинности: столбец Q","prompt":"Запиши столбец Q сверху вниз 8 цифрами (например 01010101)."},"en":{"title":"Truth table: the Q column","prompt":"Write the Q column top to bottom as 8 digits (e.g. 01010101)."},"widget":{"kind":"circuit","circuit":{"inputs":["A","B","C"],"gates":[{"id":"X","type":"XOR","in":["A","B"]},{"id":"Q","type":"AND","in":["X","C"]}],"out":"Q"},"hideOut":true,"hideMid":true},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Схема: неше жолда 1?","prompt":"Q = (A AND NOT B) OR (B AND C). Ақиқат кестесінің неше жолында Q = 1?","accept":["4"],"points":2,"ru":{"title":"Схема: в скольких строках 1?","prompt":"Q = (A AND NOT B) OR (B AND C). В скольких строках таблицы Q = 1?"},"en":{"title":"Circuit: how many rows give 1?","prompt":"Q = (A AND NOT B) OR (B AND C). In how many rows is Q = 1?"},"widget":{"kind":"circuit","circuit":{"inputs":["A","B","C"],"gates":[{"id":"N","type":"NOT","in":["B"]},{"id":"P","type":"AND","in":["A","N"]},{"id":"R","type":"AND","in":["B","C"]},{"id":"Q","type":"OR","in":["P","R"]}],"out":"Q"},"hideOut":true,"hideMid":true},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"★ Күрделі есеп: дауыс беру","prompt":"Үш төрешінің кемінде екеуі «иә» (1) десе, шам жанады. Ақиқат кестесінің Q бағанын 000-ден 111-ге дейін 8 цифрмен жаз.","accept":["00010111"],"points":3,"notes":"Схемасы: Q = (A AND B) OR (A AND C) OR (B AND C). Үлгерген оқушыға схеманы сызып көруді ұсыныңыз.","ru":{"title":"★ Сложная задача: голосование","prompt":"Лампа горит, если хотя бы двое из трёх судей сказали «да» (1). Запиши столбец Q от 000 до 111 восемью цифрами.","notes":"Схема: Q = (A AND B) OR (A AND C) OR (B AND C). Тем, кто успел, предложите нарисовать схему."},"en":{"title":"★ Hard problem: majority vote","prompt":"The lamp lights when at least two of three judges say “yes” (1). Write the Q column from 000 to 111 as 8 digits.","notes":"Circuit: Q = (A AND B) OR (A AND C) OR (B AND C). Fast students can draw it."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: NOR","prompt":"A = 0, B = 0. NOT (A OR B) неге тең?","options":["0","1","00","Анықталмайды"],"answer":1,"explanation":"A OR B = 0, ал NOT 0 = 1. Бұл — NOR вентилі.","points":1,"ru":{"title":"Тест: NOR","prompt":"A = 0, B = 0. Чему равно NOT (A OR B)?","options":["0","1","00","Не определено"],"explanation":"A OR B = 0, а NOT 0 = 1. Это вентиль NOR.","notes":"7 минут: два теста и итог. Если ошибок много, снова покажите NOR в инструменте."},"en":{"title":"Test: NOR","prompt":"A = 0, B = 0. What is NOT (A OR B)?","options":["0","1","00","Undefined"],"explanation":"A OR B = 0 and NOT 0 = 1. That is the NOR gate.","notes":"7 minutes: two tests and the wrap-up. If many are wrong, show NOR in the tool again."},"stage":"check","notes":"7 минут: екі тест және қорытынды. Қате көп болса, құралда NOR-ды қайта көрсетіңіз."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: вентиль","prompt":"Қай вентиль кірістер әртүрлі болғанда ғана 1 береді?","options":["AND","OR","NAND","XOR"],"answer":3,"explanation":"XOR кестесі: 0, 1, 1, 0. OR-дан айырмасы: 1 және 1 болғанда 0.","points":1,"ru":{"title":"Тест: вентиль","prompt":"Какой вентиль даёт 1, только если входы различны?","options":["AND","OR","NAND","XOR"],"explanation":"Таблица XOR: 0, 1, 1, 0. Отличие от OR: при 1 и 1 даёт 0."},"en":{"title":"Test: gate","prompt":"Which gate gives 1 only when the inputs differ?","options":["AND","OR","NAND","XOR"],"explanation":"XOR: 0, 1, 1, 0. Unlike OR it gives 0 for 1 and 1."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$i10$::jsonb),
    ($i10$inf10-3$i10$, $i10$2.3 Деректерді кодтау: сандар мен мәтін$i10$, $i10$Информатика$i10$, 2, $i10${"gen":"inf10-3","summary":"Бүтін сандар 8 битте: таңба биті, қосымша код, азайтуды қосуға айналдыру, толып кету. Таңбалар: ASCII, Unicode, UTF-8.","objectives":["Теріс бүтін санның 8 биттік қосымша кодын жазу және оқу","Таңбаның ASCII/Unicode кодын табу, мәтіннің UTF-8 көлемін есептеу"],"grade":10,"duration":"45 минут","prior":"Екілік жүйе, екілік қосу (2.1).","env":"ClassFlow: интерактивті слайдтар (сандар жүйесі, схемалар, кодтар) және «Көмекші кесте» (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC функциялары). Әр оқушыға құрылғы мен интернет.","source":"Информатика 10-сынып оқулығы, 2-тарау «Деректерді көрсету» (беттерін мұғалім нақтылайды). Барлық жауап бағдарламамен есептеліп тексерілген.","stages":[{"k":"warmup","min":5,"do":"Екі сұрақ: 8 биттің мүмкіндігі, 13-тің екілік жазбасы"},{"k":"together","min":10,"do":"Таңба биті, қосымша код және ASCII/Unicode кестелерін құралда көреді"},{"k":"example","min":8,"do":"Хабарды екілік кодтан оқиды; 9 − 5-ті қосумен есептейді"},{"k":"practice","min":15,"do":"4 есеп; үлгерген оқушы ★ (толып кету)"},{"k":"check","min":7,"do":"Екі тест сұрағы және қорытынды"}],"ru":{"summary":"Целые числа в 8 битах: знаковый бит, дополнительный код, вычитание через сложение, переполнение. Символы: ASCII, Unicode, UTF-8.","objectives":["Записывать и читать 8-битный дополнительный код отрицательного числа","Находить код символа в ASCII/Unicode, считать объём текста в UTF-8"],"prior":"Двоичная система, двоичное сложение (2.1).","env":"ClassFlow: интерактивные слайды (системы счисления, схемы, коды) и «Таблица-помощник» (функции DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). Каждому ученику устройство и интернет.","source":"Учебник информатики 10 класса, глава 2 «Представление данных» (страницы уточняет учитель). Все ответы вычислены и проверены программой.","stages":["Два вопроса: возможности 8 бит, 13 в двоичной","Смотрит знаковый бит, доп. код и таблицы ASCII/Unicode в инструменте","Читает сообщение из двоичного кода; считает 9 − 5 сложением","4 задачи; кто успел — ★ (переполнение)","Два тестовых вопроса и итог"]},"en":{"summary":"Whole numbers in 8 bits: the sign bit, two’s complement, subtraction by addition, overflow. Characters: ASCII, Unicode, UTF-8.","objectives":["Write and read the 8-bit two’s complement of a negative number","Find a character’s ASCII/Unicode code and the UTF-8 size of a text"],"prior":"Binary numbers and binary addition (2.1).","env":"ClassFlow: interactive slides (number systems, circuits, codes) and the “Helper sheet” (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). A device and the internet per student.","source":"Informatics Grade 10 textbook, chapter 2 “Data representation” (the teacher adds the pages). Every answer was computed and checked by a program.","stages":["Two questions: what 8 bits hold, 13 in binary","Sees the sign bit, two’s complement and ASCII/Unicode in the tools","Reads a message from binary; computes 9 − 5 by addition","4 problems; fast students take ★ (overflow)","Two test questions and the wrap-up"]}}$i10$::jsonb, $i10$[{"term":"sign bit","definition":"Таңба биті — ең сол жақтағы бит: 0 — оң, 1 — теріс сан · Знаковый бит — крайний левый: 0 — положительное, 1 — отрицательное · Sign bit — the leftmost bit: 0 positive, 1 negative"},{"term":"two’s complement","definition":"Қосымша код — |n|-ді инверсиялап, 1 қосамыз; азайту қосуға айналады · Дополнительный код — инвертируем |n| и прибавляем 1; вычитание становится сложением · Two’s complement — invert |n| and add 1; subtraction becomes addition"},{"term":"overflow","definition":"Толып кету — нәтиже разряд торына сыймай, бұрмаланады · Переполнение — результат не помещается в разрядную сетку и искажается · Overflow — the result does not fit the bits and comes out wrong"},{"term":"Unicode","definition":"Unicode — әлемдегі барлық таңбаның бірыңғай кестесі (U+0000 …); UTF-8 бір таңбаға 1–4 байт · Unicode — единая таблица всех символов (U+0000 …); UTF-8 тратит 1–4 байта на символ · Unicode — one table of every character (U+0000 …); UTF-8 uses 1–4 bytes per character"}]$i10$::jsonb, $i10$[{"type":"title","pageType":"slide","templateId":"title","title":"2.3 Деректерді кодтау: сандар мен мәтін","subtitle":"Информатика 10-сынып · 2-тарау «Деректерді көрсету»","ru":{"title":"2.3 Кодирование данных: числа и текст","subtitle":"Информатика 10 класс · глава 2 «Представление данных»"},"en":{"title":"2.3 Coding data: numbers and text","subtitle":"Informatics Grade 10 · Chapter 2 “Data representation”"},"design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: 8 бит","prompt":"8 битпен неше түрлі мән жазуға болады?","options":["8","16","256","255"],"answer":2,"explanation":"2⁸ = 256: 0-ден 255-ке дейін (255 — ең үлкені, бірақ мәндер саны 256).","points":1,"ru":{"title":"Повторение: 8 бит","prompt":"Сколько разных значений можно записать 8 битами?","options":["8","16","256","255"],"explanation":"2⁸ = 256: от 0 до 255 (255 — наибольшее, но значений 256).","notes":"5 минут. Сразу обсудите разницу 255 и 256 (наибольшее значение и число значений)."},"en":{"title":"Review: 8 bits","prompt":"How many different values can 8 bits hold?","options":["8","16","256","255"],"explanation":"2⁸ = 256: from 0 to 255 (255 is the largest, but there are 256 values).","notes":"5 minutes. Discuss 255 vs 256 (the largest value vs the number of values) right away."},"stage":"warmup","notes":"5 минут. 255 пен 256 айырмасын (ең үлкен мән және мәндер саны) бірден талқылаңыз."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Қайталау: екілік","prompt":"13 санының екілік жазбасы қандай?","options":["1101","1011","1110","10011"],"answer":0,"explanation":"13 = 8 + 4 + 1 = 1101₂.","points":1,"ru":{"title":"Повторение: двоичная","prompt":"Как записать 13 в двоичной системе?","options":["1101","1011","1110","10011"],"explanation":"13 = 8 + 4 + 1 = 1101₂."},"en":{"title":"Review: binary","prompt":"What is 13 in binary?","options":["1101","1011","1110","10011"],"explanation":"13 = 8 + 4 + 1 = 1101₂."},"stage":"warmup"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Бүтін сан 8 битте","bullets":["Таңбасыз: 0 … 255. Таңбалы: ең сол жақ бит — таңба (0 оң, 1 теріс), диапазоны −128 … 127.","Биттерді басып көр: бір ғана 8 бит екі түрлі оқылады — таңбасыз және таңбалы."],"notes":"10 минут. 13 → 127 → 128 мысалдарын көрсетіңіз: 10000000 таңбасыз 128, таңбалы −128. Сосын −13-ке өтіңіз.","ru":{"title":"Целое число в 8 битах","bullets":["Без знака: 0 … 255. Со знаком: левый бит — знак (0 плюс, 1 минус), диапазон −128 … 127.","Нажимай на биты: одни и те же 8 бит читаются двумя способами — без знака и со знаком."],"notes":"10 минут. Покажите 13 → 127 → 128: 10000000 без знака 128, со знаком −128. Затем перейдите к −13."},"en":{"title":"A whole number in 8 bits","bullets":["Unsigned: 0 … 255. Signed: the leftmost bit is the sign (0 plus, 1 minus), range −128 … 127.","Click the bits: the same 8 bits read two ways — unsigned and signed."],"notes":"10 minutes. Show 13 → 127 → 128: 10000000 is 128 unsigned, −128 signed. Then go to −13."},"widget":{"kind":"code","mode":"int","value":13},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Қосымша код: инверсия + 1","bullets":["−n кодын табу: |n|-ді 8 битпен жазамыз → барлық битті ауыстырамыз → 1 қосамыз.","Неге осылай? n + (−n) = 1 00000000: 9-шы бит сыймай тасталады да, 0 қалады. Сондықтан процессор азайтуды қосумен орындайды."],"ru":{"title":"Дополнительный код: инверсия + 1","bullets":["Код −n: пишем |n| в 8 битах → инвертируем все биты → прибавляем 1.","Зачем так? n + (−n) = 1 00000000: 9-й бит не помещается и отбрасывается, остаётся 0. Поэтому процессор вычитает сложением."]},"en":{"title":"Two’s complement: invert + 1","bullets":["Code of −n: write |n| in 8 bits → invert every bit → add 1.","Why? n + (−n) = 1 00000000: the 9th bit is dropped and 0 remains, so the processor subtracts by adding."]},"widget":{"kind":"code","mode":"int","value":-13},"stage":"together"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"explain","title":"Таңбалар: ASCII және Unicode","bullets":["ASCII: 128 таңба, 7 бит. A = 65, a = 97, 0 = 48 — әріптер ретімен келеді.","Unicode: барлық әліпби (Ә = U+04D8, Қ = U+049A). UTF-8: латын 1 байт, кирилл және қазақ әріптері 2 байт, эмодзи 4 байт."],"ru":{"title":"Символы: ASCII и Unicode","bullets":["ASCII: 128 символов, 7 бит. A = 65, a = 97, 0 = 48 — буквы идут по порядку.","Unicode: все алфавиты (Ә = U+04D8, Қ = U+049A). UTF-8: латиница 1 байт, кириллица и казахские буквы 2 байта, эмодзи 4."]},"en":{"title":"Characters: ASCII and Unicode","bullets":["ASCII: 128 characters, 7 bits. A = 65, a = 97, 0 = 48 — letters come in order.","Unicode: every alphabet (Ә = U+04D8, Қ = U+049A). UTF-8: Latin 1 byte, Cyrillic and Kazakh 2 bytes, emoji 4."]},"widget":{"kind":"code","mode":"text","value":"Hi Қ!"},"stage":"together"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"Хабарды оқы","sections":[{"h":"Шарты","text":"01001011 01111010 — ASCII кодымен жазылған екі таңба. Хабар қандай?"},{"h":"Алгоритм (қадамдар)","bullets":["Әр байтты ондыққа аударамыз: 01001011 = 64 + 8 + 2 + 1 = 75; 01111010 = 64 + 32 + 16 + 8 + 2 = 122.","ASCII: 65 = A, сондықтан 75 = K (A-дан кейінгі 10-шы). 97 = a, сондықтан 122 = z."]},{"h":"Шешімі","text":"«Kz»","hide":true}],"notes":"8 минут (мысал). Шешімді ашпас бұрын оқушылар «Мәтін» құралына Kz деп жазып тексерсін. Екінші мысал — азайтуды қосумен есептеу.","ru":{"title":"Прочитай сообщение","sections":[{"h":"Условие","text":"01001011 01111010 — два символа в ASCII. Что за сообщение?"},{"h":"Алгоритм (шаги)","bullets":["Каждый байт переводим: 01001011 = 64 + 8 + 2 + 1 = 75; 01111010 = 64 + 32 + 16 + 8 + 2 = 122.","ASCII: 65 = A, значит 75 = K (10-я после A). 97 = a, значит 122 = z."]},{"h":"Решение","text":"«Kz»","hide":true}],"notes":"8 минут (пример). Перед открытием решения пусть ученики проверят, набрав Kz в инструменте. Второй пример — вычитание сложением."},"en":{"title":"Read the message","sections":[{"h":"Task","text":"01001011 01111010 — two ASCII characters. What is the message?"},{"h":"Steps","bullets":["Convert each byte: 01001011 = 64 + 8 + 2 + 1 = 75; 01111010 = 64 + 32 + 16 + 8 + 2 = 122.","ASCII: 65 = A, so 75 = K (10 after A). 97 = a, so 122 = z."]},{"h":"Solution","text":"“Kz”","hide":true}],"notes":"8 minutes (example). Before revealing, let students type Kz in the text tool to check. The second example subtracts by adding."},"stage":"example","design":"lab"},{"type":"solution","pageType":"slide","templateId":"worked-example","kind":"exampletask","title":"9 − 5 = 9 + (−5)","sections":[{"h":"Шарты","text":"8 биттік қосымша кодпен 9 − 5 есепте."},{"h":"Алгоритм (қадамдар)","bullets":["9 = 00001001. 5 = 00000101 → инверсия 11111010 → +1 = 11111011 (бұл −5).","00001001 + 11111011 = 1 00000100. 9-шы бит тасталады."]},{"h":"Шешімі","text":"00000100 = 4 ✓","hide":true}],"ru":{"title":"9 − 5 = 9 + (−5)","sections":[{"h":"Условие","text":"Вычисли 9 − 5 в 8-битном дополнительном коде."},{"h":"Алгоритм (шаги)","bullets":["9 = 00001001. 5 = 00000101 → инверсия 11111010 → +1 = 11111011 (это −5).","00001001 + 11111011 = 1 00000100. 9-й бит отбрасываем."]},{"h":"Решение","text":"00000100 = 4 ✓","hide":true}]},"en":{"title":"9 − 5 = 9 + (−5)","sections":[{"h":"Task","text":"Compute 9 − 5 in 8-bit two’s complement."},{"h":"Steps","bullets":["9 = 00001001. 5 = 00000101 → invert 11111010 → +1 = 11111011 (that is −5).","00001001 + 11111011 = 1 00000100. Drop the 9th bit."]},{"h":"Solution","text":"00000100 = 4 ✓","hide":true}]},"stage":"example","design":"lab"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Қосымша код","prompt":"−20 санының 8 биттік қосымша кодын жаз.","accept":["11101100"],"points":2,"notes":"15 минут. Жауаптар: 11101100; −2; 67; 10; ★ −106. Құралда (2.3 слайдтары) тексеруге болады.","ru":{"title":"Дополнительный код","prompt":"Запиши 8-битный дополнительный код числа −20.","notes":"15 минут. Ответы: 11101100; −2; 67; 10; ★ −106. Можно проверять в инструментах урока."},"en":{"title":"Two’s complement","prompt":"Write the 8-bit two’s complement of −20.","notes":"15 minutes. Answers: 11101100; −2; 67; 10; ★ −106. The lesson’s tools can check."},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Кодты оқу","prompt":"11111110 — 8 биттік таңбалы сан (қосымша код). Ол ондықта неге тең?","accept":["-2","−2"],"points":2,"ru":{"title":"Чтение кода","prompt":"11111110 — 8-битное число со знаком (доп. код). Чему оно равно в десятичной?"},"en":{"title":"Reading a code","prompt":"11111110 is a signed 8-bit number (two’s complement). What is it in decimal?"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"ASCII","prompt":"A әрпінің ASCII коды — 65. C әрпінің коды қандай (ондықта)?","accept":["67"],"points":2,"ru":{"title":"ASCII","prompt":"Код буквы A в ASCII — 65. Каков код буквы C (в десятичной)?"},"en":{"title":"ASCII","prompt":"The ASCII code of A is 65. What is the code of C (in decimal)?"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"UTF-8 көлемі","prompt":"«Сәлем» сөзі UTF-8 кодтауында неше байт алады?","accept":["10"],"points":2,"ru":{"title":"Объём в UTF-8","prompt":"Сколько байт занимает слово «Сәлем» в UTF-8?"},"en":{"title":"Size in UTF-8","prompt":"How many bytes does the word «Сәлем» take in UTF-8?"},"widget":{"kind":"code","mode":"text","value":"Hello"},"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"★ Күрделі есеп: толып кету","prompt":"8 биттік таңбалы сандар: 100 + 50 есептелгенде қандай сан шығады (ондықта)?","accept":["-106","−106"],"points":3,"notes":"150 = 10010110: таңба биті 1 болып кетті, таңбалы оқығанда 150 − 256 = −106. Бұл — толып кету; ойындардағы «ұпай теріс болып кетті» қатесінің себебі.","ru":{"title":"★ Сложная задача: переполнение","prompt":"8-битные числа со знаком: какое число получится при 100 + 50 (в десятичной)?","notes":"150 = 10010110: знаковый бит стал 1, со знаком это 150 − 256 = −106. Это переполнение — причина ошибок «очки стали отрицательными» в играх."},"en":{"title":"★ Hard problem: overflow","prompt":"Signed 8-bit numbers: what does 100 + 50 give (in decimal)?","notes":"150 = 10010110: the sign bit became 1, so signed it reads 150 − 256 = −106. That is overflow — the cause of “the score went negative” bugs."},"stage":"practice"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: ASCII","prompt":"Стандарт ASCII кестесінде неше таңба бар?","options":["256","65 536","128","100"],"answer":2,"explanation":"ASCII — 7 бит: 2⁷ = 128 таңба. 256 — кеңейтілген 8 биттік кестелер.","points":1,"ru":{"title":"Тест: ASCII","prompt":"Сколько символов в стандартной таблице ASCII?","options":["256","65 536","128","100"],"explanation":"ASCII — 7 бит: 2⁷ = 128 символов. 256 — расширенные 8-битные таблицы.","notes":"7 минут: два теста и итог."},"en":{"title":"Test: ASCII","prompt":"How many characters does standard ASCII have?","options":["256","65 536","128","100"],"explanation":"ASCII is 7 bits: 2⁷ = 128 characters. 256 are the extended 8-bit tables.","notes":"7 minutes: two tests and the wrap-up."},"stage":"check","notes":"7 минут: екі тест және қорытынды."},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест: таңба","prompt":"Таңбалы 8 биттік санның теріс екенін қай бит көрсетеді?","options":["Ең оң жақ","Ең сол жақ","Ортаңғы","Бәрі 1 болуы керек"],"answer":1,"explanation":"Ең сол жақ (жоғары) бит — таңба биті: 1 болса, сан теріс.","points":1,"ru":{"title":"Тест: знак","prompt":"Какой бит показывает, что 8-битное число со знаком отрицательное?","options":["Крайний правый","Крайний левый","Средний","Все должны быть 1"],"explanation":"Крайний левый (старший) бит — знаковый: если 1, число отрицательное."},"en":{"title":"Test: sign","prompt":"Which bit shows that a signed 8-bit number is negative?","options":["The rightmost","The leftmost","The middle one","All must be 1"],"explanation":"The leftmost (highest) bit is the sign bit: 1 means negative."},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$i10$::jsonb),
    ($i10$inf10-4$i10$, $i10$2.4 Өзіңді тексер: деректерді көрсету$i10$, $i10$Информатика$i10$, 3, $i10${"gen":"inf10-4","summary":"Тарау бойынша жұмыс: 3 практикалық есеп және 7 тест, әр тестте 4 нұсқа — көршілерде әртүрлі нұсқа.","objectives":["2-тарау бойынша білімін тексеру"],"grade":10,"duration":"45 минут","prior":"2.1–2.3 сабақтары.","env":"ClassFlow: интерактивті слайдтар (сандар жүйесі, схемалар, кодтар) және «Көмекші кесте» (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC функциялары). Әр оқушыға құрылғы мен интернет.","source":"Информатика 10-сынып оқулығы, 2-тарау «Деректерді көрсету» (беттерін мұғалім нақтылайды). Барлық жауап бағдарламамен есептеліп тексерілген.","stages":[{"k":"warmup","min":5,"do":"Ереже және бір жылы кіріс сұрағы"},{"k":"practice","min":15,"do":"3 есеп (көмекші кестемен тексеруге болады); үлгерген оқушы ★"},{"k":"check","min":25,"do":"7 тест, әр оқушыда өз нұсқасы"}],"ru":{"summary":"Работа по главе: 3 практические задачи и 7 тестов, в каждом 4 варианта — у соседей разные варианты.","objectives":["Проверить знания по главе 2"],"prior":"Уроки 2.1–2.3.","env":"ClassFlow: интерактивные слайды (системы счисления, схемы, коды) и «Таблица-помощник» (функции DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). Каждому ученику устройство и интернет.","source":"Учебник информатики 10 класса, глава 2 «Представление данных» (страницы уточняет учитель). Все ответы вычислены и проверены программой.","stages":["Правила и один вопрос-разминка","3 задачи (можно проверять в таблице-помощнике); кто успел — ★","7 тестов, у каждого свой вариант"]},"en":{"summary":"Chapter work: 3 practical problems and 7 tests with 4 variants each — neighbours get different variants.","objectives":["Check what you know of chapter 2"],"prior":"Lessons 2.1–2.3.","env":"ClassFlow: interactive slides (number systems, circuits, codes) and the “Helper sheet” (DEC2BIN, BIN2DEC, DEC2HEX, HEX2DEC). A device and the internet per student.","source":"Informatics Grade 10 textbook, chapter 2 “Data representation” (the teacher adds the pages). Every answer was computed and checked by a program.","stages":["The rules and one warm-up question","3 problems (the helper sheet may check); fast students take ★","7 tests, each student has a variant"]}}$i10$::jsonb, $i10$[{"term":"variant","definition":"Нұсқа — бір тест сұрағының әртүрлі сандармен жазылған түрі · Вариант — тот же вопрос с другими числами · Variant — the same question with other numbers"},{"term":"base","definition":"Жүйенің негізі — цифрлар саны · Основание системы — число цифр · Base — the number of digits"},{"term":"truth table","definition":"Ақиқат кестесі — кірістердің барлық комбинациясы мен шығысы · Таблица истинности — все комбинации входов и выход · Truth table — every input combination and the output"}]$i10$::jsonb, $i10$[{"type":"title","pageType":"slide","templateId":"title","title":"2.4 Өзіңді тексер","subtitle":"Информатика 10-сынып · 2-тарау «Деректерді көрсету»","ru":{"title":"2.4 Проверь себя","subtitle":"Информатика 10 класс · глава 2 «Представление данных»"},"en":{"title":"2.4 Check yourself","subtitle":"Informatics Grade 10 · Chapter 2 “Data representation”"},"design":"lab"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Жұмыс ережесі","bullets":["3 есеп + 7 тест. Әр тесттің 4 нұсқасы бар: көршіңнің сұрағы басқа, көшіру көмектеспейді.","Тест бір-ақ рет жіберіледі. Мұғалім келесі слайдқа өткенде 5 секунд қалады — асықпа, бірақ кешікпе."],"ru":{"title":"Правила работы","bullets":["3 задачи + 7 тестов. У каждого теста 4 варианта: у соседа другой вопрос, списывание не поможет.","Тест отправляется один раз. Когда учитель переходит дальше, остаётся 5 секунд."],"notes":"5 минут. Включите в правилах «Автоматическая отправка заданий»: каждый тест откроется сам при переходе на слайд."},"en":{"title":"The rules","bullets":["3 problems + 7 tests. Each test has 4 variants: your neighbour’s question differs, copying will not help.","A test is sent once. When the teacher moves on, you have 5 more seconds."],"notes":"5 minutes. Turn on “Send tasks automatically” in the rules: each test opens by itself when you reach its slide."},"stage":"warmup","notes":"5 минут. Ережелер панелінде «Тапсырманы автоматты жіберу» ережесін қосыңыз: әр тест слайдқа өткенде өзі ашылады.","design":"lab"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Жылы кіріс","prompt":"Қай жүйеде 9 цифры жоқ?","options":["Ондық","16-лық","Сегіздік","Ешқайсысында"],"answer":2,"explanation":"Сегіздікте цифрлар 0–7 ғана.","points":1,"ru":{"title":"Разминка","prompt":"В какой системе нет цифры 9?","options":["Десятичной","16-ричной","Восьмеричной","Ни в какой"],"explanation":"В восьмеричной только цифры 0–7."},"en":{"title":"Warm-up","prompt":"Which system has no digit 9?","options":["Decimal","Hexadecimal","Octal","None"],"explanation":"Octal uses only 0–7."},"stage":"warmup"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп 1: 16-лық қосу","prompt":"1A₁₆ + 0F₁₆ = ?₁₆","accept":["29"],"points":2,"notes":"15 минут. Жауаптар: 29 (26 + 15 = 41 = 29₁₆), 1001, 11110110; ★ 6.","ru":{"title":"Задача 1: сложение в 16-ричной","prompt":"1A₁₆ + 0F₁₆ = ?₁₆","notes":"15 минут. Ответы: 29 (26 + 15 = 41 = 29₁₆), 1001, 11110110; ★ 6."},"en":{"title":"Problem 1: hex addition","prompt":"1A₁₆ + 0F₁₆ = ?₁₆","notes":"15 minutes. Answers: 29 (26 + 15 = 41 = 29₁₆), 1001, 11110110; ★ 6."},"helper":true,"stage":"practice"},{"type":"task","pageType":"interactive","templateId":"short-answer","kind":"practice","title":"Есеп 2: ақиқат кестесі","prompt":"Q = NOT (A XOR B). Q бағанын (00, 01, 10, 11 ретімен) 4 цифрмен жаз.","accept":["1001"],"points":2,"ru":{"title":"Задача 2: таблица истинности","prompt":"Q = NOT (A XOR B). Запиши столбец Q (в порядке 00, 01, 10, 11) четырьмя цифрами."},"en":{"title":"Problem 2: truth table","prompt":"Q = NOT (A XOR B). Write the Q column (order 00, 01, 10, 11) as 4 digit