үйеге аудар.","options":["11001010","10010011","11000111","11001001"],"answer":3,"explanation":"201 = 11001001₂ (2-ге бөліп, қалдықтарды төменнен оқимыз / делим на 2 / divide by 2)"}],"qtext":[{"prompt":"45 санын екілік жүйеге аудар.","options":["101101","101110","101011","101111"]},{"prompt":"83 санын екілік жүйеге аудар.","options":["1010100","1100101","1010011","1010001"]},{"prompt":"108 санын екілік жүйеге аудар.","options":["1101101","1101100","0011011","1101010"]},{"prompt":"201 санын екілік жүйеге аудар.","options":["11001010","10010011","11000111","11001001"]}],"explanation":"45 = 101101₂ (2-ге бөліп, қалдықтарды төменнен оқимыз / делим на 2 / divide by 2)","ru":{"title":"Тест 1 · Перевод 10 → 2","prompt":"У каждого свой вариант (A–D). Вопрос и ответы — на твоём телефоне.","qtext":[{"prompt":"Переведи 45 в двоичную систему.","options":["101101","101110","101011","101111"]},{"prompt":"Переведи 83 в двоичную систему.","options":["1010100","1100101","1010011","1010001"]},{"prompt":"Переведи 108 в двоичную систему.","options":["1101101","1101100","0011011","1101010"]},{"prompt":"Переведи 201 в двоичную систему.","options":["11001010","10010011","11000111","11001001"]}],"notes":"25 минут: 7 тестов. С правилом автоотправки давайте ~3 минуты на тест и переходите дальше. В «Ответах» перед ответом стоит буква варианта."},"en":{"title":"Test 1 · Convert 10 → 2","prompt":"Everyone has their own variant (A–D). The question and options are on your phone.","qtext":[{"prompt":"Convert 45 to binary.","options":["101101","101110","101011","101111"]},{"prompt":"Convert 83 to binary.","options":["1010100","1100101","1010011","1010001"]},{"prompt":"Convert 108 to binary.","options":["1101101","1101100","0011011","1101010"]},{"prompt":"Convert 201 to binary.","options":["11001010","10010011","11000111","11001001"]}],"notes":"25 minutes: 7 tests. With the auto rule on, allow ~3 minutes per test, then move on. In “Answers” each answer shows its variant letter."},"stage":"check","n