0001 → 11111110 → +1 = 11111111","ru":{"title":"Тест 6 · Дополнительный код","prompt":"У каждого свой вариант (A–D). Вопрос и ответы — на твоём телефоне.","qtext":[{"prompt":"8-битный дополнительный код числа -1?","options":["10000001","11111110","11111111","00000001"]},{"prompt":"8-битный дополнительный код числа -8?","options":["10001000","11111000","11110111","00001000"]},{"prompt":"8-битный дополнительный код числа -3?","options":["10000011","11111100","00000011","11111101"]},{"prompt":"8-битный дополнительный код числа -16?","options":["11110000","10010000","11101111","00010000"]}]},"en":{"title":"Test 6 · Two’s complement","prompt":"Everyone has their own variant (A–D). The question and options are on your phone.","qtext":[{"prompt":"The 8-bit two’s complement of -1?","options":["10000001","11111110","11111111","00000001"]},{"prompt":"The 8-bit two’s complement of -8?","options":["10001000","11111000","11110111","00001000"]},{"prompt":"The 8-bit two’s complement of -3?","options":["10000011","11111100","00000011","11111101"]},{"prompt":"The 8-bit two’s complement of -16?","options":["11110000","10010000","11101111","00010000"]}]},"stage":"check"},{"type":"quiz","pageType":"interactive","templateId":"single-choice","kind":"check","title":"Тест 7 · ASCII","prompt":"Әр оқушыда өз нұсқасы (A–D). Сұрақ пен жауаптар телефоныңда.","points":1,"qvariants":[{"prompt":"A = 65, a = 97. «B» таңбасының ASCII коды?","options":["67","66","65","98"],"answer":1,"explanation":"«B» = 66"},{"prompt":"A = 65, a = 97. «F» таңбасының ASCII коды?","options":["71","69","102","70"],"answer":3,"explanation":"«F» = 70"},{"prompt":"A = 65, a = 97. «b» таңбасының ASCII коды?","options":["98","99","97","66"],"answer":0,"explanation":"«b» = 98"},{"prompt":"A = 65, a = 97. «d» таңбасының ASCII коды?","options":["101","99","100","68"],"answer":2,"explanation":"«d» = 100"}],"qtext":[{"prompt":"A = 65, a = 97. «B» таңбасының ASCII коды?","options":["67","66","65","98"]},{"prompt":"A = 65, a = 97. «F» таңбасының ASCII коды?","options":["71","69","102","70"]},{"prompt":"A = 65, a = 97. «b» таңбасының ASCII коды?","options":["98","99","97","66"]},{"prompt":"A = 65, a = 97. «d» таңбасының ASCII коды?","options":["101","99","100","68"]}],"explanation":"«B» = 66","ru":{"title":"Тест 7 · ASCII","prompt":"У каждого свой вариант (A–D). Вопрос и ответы — на твоём телефоне.","qtext":[{"prompt":"A = 65, a = 97. Код ASCII символа «B»?","options":["67","66","65","98"]},{"prompt":"A = 65, a = 97. Код ASCII символа «F»?","options":["71","69","102","70"]},{"prompt":"A = 65, a = 97. Код ASCII символа «b»?","options":["98","99","97","66"]},{"prompt":"A = 65, a = 97. Код ASCII символа «d»?","options":["101","99","100","68"]}]},"en":{"title":"Test 7 · ASCII","prompt":"Everyone has their own variant (A–D). The question and options are on your phone.","qtext":[{"prompt":"A = 65, a = 97. The ASCII code of “B”?","options":["67","66","65","98"]},{"prompt":"A = 65, a = 97. The ASCII code of “F”?","options":["71","69","102","70"]},{"prompt":"A = 65, a = 97. The ASCII code of “b”?","options":["98","99","97","66"]},{"prompt":"A = 65, a = 97. The ASCII code of “d”?","options":["101","99","100","68"]}]},"stage":"check"},{"type":"content","pageType":"slide","templateId":"explanation","kind":"check","title":"Қорытынды: бүгін не үйрендім?","bullets":["Бүгін мен … үйрендім (өз сөзіңмен жалғастыр).","Ең қызықты бөлігі: …","Маған әлі түсініксіз: …"],"ru":{"title":"Итог: что я узнал сегодня?","bullets":["Сегодня я научился … (продолжи своими словами).","Самое интересное: …","Мне пока непонятно: …"],"notes":"Ученики дописывают три предложения в тетрадь, 2–3 ученика читают вслух. Ответы «непонятно» разберите в начале следующего урока."},"en":{"title":"Wrap-up: what did I learn today?","bullets":["Today I learned … (finish in your own words).","The most interesting part: …","I still do not understand: …"],"notes":"Students finish three sentences in a notebook; 2–3 read aloud. Revisit the “do not understand” answers at the start of the next lesson."},"stage":"check","notes":"Оқушылар үш сөйлемді дәптерге жазады, 2–3 оқушы дауыстап оқиды. «Түсініксіз» жауаптарын келесі сабақтың басында қайталаңыз.","design":"lab"}]$i10$::jsonb)
  ) as t(gen, title, subject, position, plan, terms, slides)
  loop
    select l.id into v_lesson from public.cf_lessons l where l.school_id = v_school and l.plan->>'gen' = v_spec.gen limit 1;
    if v_lesson is null then
      insert into public.cf_lessons (school_id, owner_id, title, subject, plan, slides, terms)
      values (v_school, v_owner, v_spec.title, v_spec.subject, v_spec.plan, v_spec.slides, v_spec.terms) returning id into v_lesson;
    else
      update public.cf_lessons set title = v_spec.title, subject = v_spec.subject, plan = v_spec.plan, slides = v_spec.slides, terms = v_spec.terms, updated_at = now() where id = v_lesson;
    end if;
    v_ids := v_ids || v_lesson;
    insert into public.cf_curr_lessons (lesson_id, module_id, position) values (v_lesson, v_module, 100 + v_spec.position)
    on conflict (lesson_id) do update set module_id = excluded.module_id, position = excluded.position;
    v_lesson := null;
  end loop;
  delete from public.cf_curr_lessons where module_id = v_module and not (lesson_id = any(v_ids));
  update public.cf_curr_lessons set position = position - 100 where module_id = v_module and position >= 100;
end;
$info10$;
